// Placeholder types for when bindings are not yet available
// These match the WIT types defined in wit/deps/postgres/wit/types.wit
// Placeholder types matching WIT types
// These will be replaced with actual generated types once wit_bindgen bindings are available
#[derive(Debug, Clone)]
pub enum PgValue {
    Text(String),
    Int32(i32),
    Int64(i64),
    Float32((u64, i16, i8)), // hashable-f64: (mantissa, exp, sign)
    Float64((u64, i16, i8)), // hashable-f64: (mantissa, exp, sign)
    Bool(bool),
    Null,
}

#[derive(Debug)]
pub struct ResultRowEntry {
    pub column_name: String,
    pub value: PgValue,
}

pub type ResultRow = Vec<ResultRowEntry>;

#[derive(Debug)]
pub enum QueryError {
    InvalidParams(String),
    InvalidQuery(String),
    Unexpected(String),
}

