/// Query all entities from ir_entities table
pub fn query_entities() -> Result<Vec<Value>, String> {
    // NOTE: This function will use wit_bindgen generated bindings once available
    // For now, it uses placeholder implementation
    // The actual implementation will use wasmcloud::postgres::query::query()
    // and wasmcloud::postgres::types::{PgValue, ResultRow, QueryError}
    
    match query(
        "SELECT entity_id, entity_type, name, jsonld_data, llm_label, embed_hint, image_prompt, video_prompt, embedding_id, created_at, updated_at FROM ir_entities ORDER BY created_at DESC",
        &[],
    ) {
        Ok(rows) => {
            let mut entities = Vec::new();
            for row in rows {
                let mut entity = serde_json::Map::new();
                // ResultRow is a list of result-row-entry (column-name, value)
                for entry in row {
                    let value = match &entry.value {
                        PgValue::Text(s) => {
                            if entry.column_name == "jsonld_data" {
                                // Parse JSON-LD data
                                serde_json::from_str(s).unwrap_or(Value::String(s.clone()))
                            } else {
                                Value::String(s.clone())
                            }
                        },
                        PgValue::Int32(n) => Value::Number((*n).into()),
                        PgValue::Int64(n) => Value::Number((*n).into()),
                        PgValue::Float32(f) => {
                            // Convert hashable-f64 to f64
                            let (mantissa, exp, sign) = *f;
                            let f64_val = if sign == 1 {
                                -(mantissa as f64) * 2.0_f64.powi(exp as i32)
                            } else {
                                (mantissa as f64) * 2.0_f64.powi(exp as i32)
                            };
                            Value::Number(serde_json::Number::from_f64(f64_val).unwrap_or(0.into()))
                        },
                        PgValue::Float64(f) => {
                            // Convert hashable-f64 to f64
                            let (mantissa, exp, sign) = *f;
                            let f64_val = if sign == 1 {
                                -(mantissa as f64) * 2.0_f64.powi(exp as i32)
                            } else {
                                (mantissa as f64) * 2.0_f64.powi(exp as i32)
                            };
                            Value::Number(serde_json::Number::from_f64(f64_val).unwrap_or(0.into()))
                        },
                        PgValue::Bool(b) => Value::Bool(*b),
                        PgValue::Null => Value::Null,
                        _ => Value::String(format!("{:?}", entry.value)),
                    };
                    entity.insert(entry.column_name.clone(), value);
                }
                entities.push(Value::Object(entity));
            }
            Ok(entities)
        },
        Err(e) => Err(format!("Query failed: {:?}", e)),
    }
}

